import math
from scipy.stats import norm

def bs_delta(S, K, T, r, sigma, option_type='call'):
    d1 = (math.log(S/K) + (r + 0.5*sigma**2)*T) / (sigma*math.sqrt(T))
    if option_type == 'call':
        return norm.cdf(d1)
    else:
        return norm.cdf(d1) - 1

def bs_price(S, K, T, r, sigma, option_type='call'):
    d1 = (math.log(S/K) + (r + 0.5*sigma**2)*T) / (sigma*math.sqrt(T))
    d2 = d1 - sigma*math.sqrt(T)
    if option_type == 'call':
        return S*norm.cdf(d1) - K*math.exp(-r*T)*norm.cdf(d2)
    else:
        return K*math.exp(-r*T)*norm.cdf(-d2) - S*norm.cdf(-d1)

S = 100
r = 0.05
T = 30/365  # 30 DTE

# Test different IV levels
for sigma in [0.20, 0.25, 0.30]:
    print(f"\n=== IV = {sigma*100:.0f}%, 30 DTE, Stock = $100 ===")

    # Find call strike for target deltas
    for target_delta in [0.20, 0.25, 0.30, 0.35]:
        # Binary search for strike
        lo, hi = 100, 130
        for _ in range(100):
            mid = (lo + hi) / 2
            d = bs_delta(S, mid, T, r, sigma, 'call')
            if d > target_delta:
                lo = mid
            else:
                hi = mid
        K = mid
        price = bs_price(S, K, T, r, sigma, 'call')
        pct_otm = (K - S) / S * 100
        print(f"  Call {target_delta:.2f}d: K=${K:.2f}, {pct_otm:.1f}% OTM, premium=${price:.2f}")

    # Find put strike for target deltas
    for target_delta in [0.20, 0.25, 0.30, 0.35]:
        # Binary search for strike
        lo, hi = 70, 100
        for _ in range(100):
            mid = (lo + hi) / 2
            d = bs_delta(S, mid, T, r, sigma, 'put')
            if d < -target_delta:
                lo = mid
            else:
                hi = mid
        K = mid
        price = bs_price(S, K, T, r, sigma, 'put')
        pct_otm = (S - K) / S * 100
        print(f"  Put  {target_delta:.2f}d: K=${K:.2f}, {pct_otm:.1f}% OTM, premium=${price:.2f}")

